ALTER TABLE "commerce"."pages" DROP CONSTRAINT "pages_slug_not_reserved";--> statement-breakpoint
ALTER TABLE "commerce"."platform_settings" ADD COLUMN "locales" text[] DEFAULT '{en-GB}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "commerce"."pages" ADD CONSTRAINT "pages_slug_not_reserved" CHECK ("commerce"."pages"."store_id" is not null or "commerce"."pages"."type" <> 'page' or split_part("commerce"."pages"."slug", '/', 1) not in ('account', 'admin', 'api', 'app', 'auth', 'blog', 'category', 'cookies', 'da', 'en', 'forgot-password', 'help', 'mail', 'nb', 'nn', 'no', 'platform', 'robots', 's', 'setup', 'sign-in', 'sign-up', 'sitemap', 'status', 'stores', 'support', 'sv', 'tag', 'themes', 'unsubscribe', 'www'));--> statement-breakpoint
ALTER TABLE "commerce"."platform_settings" ADD CONSTRAINT "platform_settings_locales" CHECK (coalesce("commerce"."platform_settings"."locales"[1] = 'en-GB', false) and "commerce"."platform_settings"."locales" <@ array['en-GB', 'nb-NO']::text[]);